from pathlib import Path
import hashlib,json,subprocess,shutil
root=Path('/workspace/superset');out=Path('/workspace/scratch/parity-123');prior=Path('/workspace/scratch/parity-122');dist=root/'apps/desktop/dist';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source=subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip()
product=json.loads((prior/'product-snapshot.json').read_text());assert product['sourceCommit']=='8af01d71471d2fae4221b4655ddcf26d71f19b23';assert all(sha(dist/r['path'])==r['sha256'] for r in product['files']);shutil.copyfile(prior/'product-snapshot.json',out/'product-snapshot.json')
old=json.loads((prior/'fixture-snapshot.json').read_text());fixtures={p:sha(root/p) for p in old};changed=[p for p,h in old.items() if fixtures[p]!=h];assert changed==['apps/desktop/scripts/verify-workstation-browser-ui.mjs'],changed
new='apps/desktop/scripts/verify-workstation-browser-import-login-cli-ui.mjs';fixtures[new]=sha(root/new);assert len(fixtures)==85;(out/'fixture-snapshot.json').write_text(json.dumps(fixtures,indent=2)+'\n');(out/'fixture-source.json').write_text(json.dumps({'source':source,'compiledSource':product['sourceCommit'],'count':len(fixtures)},indent=2)+'\n')
paths=subprocess.check_output(['git','ls-files','packages','lingui.config.ts','bun.lock'],cwd=root,text=True).splitlines();cliGraph={p:sha(root/p) for p in paths if (root/p).is_file()};cliGraph.update({str(p.relative_to(root)):sha(p) for p in (root/'packages/i18n/locales').glob('*/messages.ts')});(out/'source-cli-snapshot.json').write_text(json.dumps(cliGraph,indent=2)+'\n')
assert sha(dist/'resources/bin/superset')=='f89552f7f0d9402b8f48eb2e4ecf0b97eaa5cd5438b64658ccf79534515487bb'
proof={'compiledSource':product['sourceCommit'],'cliAndFixtureSource':source,'compiledFiles':len(product['files']),'fixtureCount':len(fixtures),'manifestSha256':sha(out/'product-snapshot.json'),'noNewDesktopBuild':True,'bundledCliNotRebuilt':True};(out/'product-preservation.json').write_text(json.dumps(proof,indent=2)+'\n');print(proof)
